{"code":"const spawns = {};
const roles = [
  { name: "architect", provider: "magpie", model: "codex/gpt-6.1-sol",
    description: "Answer a tiny arithmetic question internally and reply with just the number.",
    prompt: "Work out what 2+2 is internally (do not show the work), then reply with just the number." },
  { name: "implementer", provider: "corp", model: "DeepSeek-V4.1-Flash-1017",
    description: "Role-table verification probe: reply READY.",
    prompt: "Reply READY" },
  { name: "reviewer", provider: "corp", model: "GLM-5.3-Flash",
    description: "Role-table verification probe: reply READY.",
    prompt: "Reply READY" },
  { name: "validator", provider: "magpie", model: "auto/mimo-v2.6-flash",
    description: "Role-table verification probe: reply READY.",
    prompt: "Reply READY" },
];
for (const r of roles) {
  try {
    const res = await tools.spawn_teammate({
      name: r.name,
      description: r.description,
      prompt: r.prompt,
      context: "fresh",
      agent_options: { provider: r.provider, model: r.model },
    });
    spawns[r.name] = { ok: true, member: res.member };
  } catch (e) {
    spawns[r.name] = { ok: false, error: (e as Error).message, toolName: (e as any).toolName };
  }
}
console.log(JSON.stringify(spawns, null, 2));","description":"Spawn four teammates with role-table routes"}

