{"code":"const ids = ["task-1","task-2","task-3","task-4"];
const out = [];
for (const id of ids) {
  const t = await tools.team_task_get({ task_id: id });
  const upd = await tools.team_task_update({ task_id: id, expected_revision: t.revision, action: "claim" });
  const done = await tools.team_task_update({ task_id: id, expected_revision: upd.revision, action: "complete" });
  out.push(done);
}
console.log(JSON.stringify(out, null, 2));","description":"Claim and complete the four tasks in order"}

